#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../../../frontend" && pwd)"
cd "$ROOT"

fuser -k 3019/tcp 2>/dev/null || true
fuser -k 18080/tcp 2>/dev/null || true
pkill -f pr139-responsive-evidence-mock-api.mjs 2>/dev/null || true
pkill -f pr139-evidence-server.mjs 2>/dev/null || true
sleep 1

# Fixtures are generated by Playwright globalSetup and removed by globalTeardown.
node scripts/pr139-cleanup-evidence-fixtures.mjs >/dev/null 2>&1 || true
rm -rf .next/cache
mkdir -p ../docs/evidence/jp-ui-perf-stability-01a-media

export PLAYWRIGHT_PORT=3019
export PR139_MOCK_API_PORT=18080
export LARAVEL_URL=http://127.0.0.1:18080
export NEXT_PUBLIC_LARAVEL_URL=http://127.0.0.1:18080
export OTA_ALLOW_CONTENT_FIXTURE=false
export NEXT_PUBLIC_ALLOW_CONTENT_FIXTURES=false

npx playwright test -c playwright.pr139-responsive-evidence.config.ts 2>&1 | tee /tmp/pr139-playwright.txt
echo "PLAYWRIGHT_EXIT=${PIPESTATUS[0]}"

if [[ -d public/_evidence/pr139-responsive ]]; then
  echo "GENERATED_FIXTURE_DIRECTORY_CLEAN_AFTER_TEST=NO"
  ls -la public/_evidence/pr139-responsive | head
  exit 2
fi
echo "GENERATED_FIXTURE_DIRECTORY_CLEAN_AFTER_TEST=YES"

fuser -k 3019/tcp 2>/dev/null || true
fuser -k 18080/tcp 2>/dev/null || true
